const base='http://127.0.0.1:3000/api';
async function call(path,{token,method='GET',body}={}){
  const response=await fetch(base+path,{method,headers:{...(token?{Authorization:`Bearer ${token}`}:{}) ,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});
  const payload=await response.json(); if(!response.ok) throw Object.assign(new Error(`${response.status} ${payload.error?.message}`),{status:response.status,code:payload.error?.code,details:payload.error?.details}); return payload.data;
}
async function login(username,password){return (await call('/auth/login',{method:'POST',body:{username,password}})).token;}
async function expectFailure(label,fn){try{await fn();throw new Error(`${label} unexpectedly succeeded`);}catch(error){if(error.message.endsWith('unexpectedly succeeded'))throw error;return {label,status:error.status,code:error.code};}}
const summary={};
const admin=await login('admin','admin123'); const hr=await login('hr','hr123'); const employee=await login('employee','employee123');
try{
  const departments=await call('/departments',{token:hr}); const positions=await call('/positions?pageSize=100',{token:hr});
