  const created=await call('/employees',{token:hr,method:'POST',body:{employeeNo:'E900',name:'自动化测试员',gender:'OTHER',birthDate:'1996-01-01',idCard:'110101199601010099',phone:'13800000900',email:'test@example.local',address:'测试地址',emergencyContact:'测试联系人',emergencyPhone:'13900000900',departmentId:dept.id,positionId:pos.id,hireDate:'2026-01-02',baseSalary:12345}});
  const updated=await call(`/employees/${created.id}`,{token:hr,method:'PUT',body:{...created,departmentId:6,positionId:6}});
  const transferred=await call(`/employees/${created.id}/transfer`,{token:hr,method:'POST',body:{departmentId:5,positionId:5}});
  const offboarded=await call(`/employees/${created.id}/offboard`,{token:hr,method:'POST',body:{leaveDate:'2026-10-12',reason:'自动化测试'}});
  await call(`/employees/${created.id}`,{token:hr,method:'DELETE'});
  summary.employeeFlow={created:created.employeeNo,updated:updated.name,transferred:transferred.positionName,status:offboarded.status,deleted:true};

  const leave=await call('/leaves',{token:employee,method:'POST',body:{type:'ANNUAL',startDate:'2026-12-01',endDate:'2026-12-02',reason:'自动化测试请假',submit:true}});
  const approved=await call(`/leaves/${leave.id}/approve`,{token:hr,method:'POST',body:{comment:'自动化审批通过'}});
  const invalidLeave=await expectFailure('approved leave cancel',()=>call(`/leaves/${leave.id}/cancel`,{token:hr,method:'POST',body:{}}));
  summary.leaveFlow={created:leave.status,approved:approved.status,invalidTransition:invalidLeave.code};

  const generation=await call('/payrolls/generate',{token:hr,method:'POST',body:{month:'2026-11'}});
  const payrollList=await call('/payrolls?month=2026-11&pageSize=100',{token:hr}); const payroll=payrollList[0];
  const payrollUpdated=await call(`/payrolls/${payroll.id}`,{token:hr,method:'PUT',body:{month:'2026-11',employeeId:payroll.employee_id,baseSalary:payroll.base_salary,performanceBonus:payroll.performance_bonus+100,socialSecurity:payroll.social_security,tax:payroll.tax,deduction:payroll.deduction}});
  const payrollConfirmed=await call(`/payrolls/${payroll.id}/confirm`,{token:hr,method:'POST',body:{}});
  const payrollPaid=await call(`/payrolls/${payroll.id}/paid`,{token:hr,method:'POST',body:{}});
  const locked=await expectFailure('paid payroll edit',()=>call(`/payrolls/${payroll.id}`,{token:hr,method:'PUT',body:{month:'2026-11',employeeId:payroll.employee_id,baseSalary:1}}));
  summary.payrollFlow={generated:generation.generated,updated:payrollUpdated.status,confirmed:payrollConfirmed.status,paid:payrollPaid.status,locked:locked.code};

  const user=await call('/admin/users',{token:admin,method:'POST',body:{username:'apitestuser',password:'test123',role:'EMPLOYEE',employeeId:null,isActive:true}});
  const userUpdated=await call(`/admin/users/${user.id}`,{token:admin,method:'PUT',body:{username:'apitestuser',role:'HR',employeeId:null,isActive:true}});
  await call(`/admin/users/${user.id}/password`,{token:admin,method:'PUT',body:{password:'newtest123'}});
  await call(`/admin/users/${user.id}`,{token:admin,method:'DELETE'});
  const audit=await call('/admin/audit-logs?pageSize=100',{token:admin});
  summary.userFlow={created:user.username,role:userUpdated.role,deleted:true}; summary.auditActions=[...new Set(audit.map(x=>x.action))].filter(x=>['CREATE_EMPLOYEE','TRANSFER_EMPLOYEE','OFFBOARD_EMPLOYEE','DELETE_EMPLOYEE','APPROVE_LEAVE','UPDATE_PAYROLL','CONFIRM_PAYROLL','PAY_PAYROLL','UPDATE_USER_PERMISSION','DELETE_USER'].includes(x));
} finally {
  await call('/admin/reset-demo',{token:admin,method:'POST',body:{confirmation:'RESET'}}).catch(()=>{});
}
console.log(JSON.stringify(summary,null,2));
