import os from 'node:os';
import path from 'node:path';
const dbFile=path.join(os.tmpdir(),`hr-clean-${Date.now()}.sqlite`); const port='3011';
const child=spawn(process.execPath,['src/index.js'],{cwd:path.resolve('server'),env:{...process.env,PORT:port,DB_FILE:dbFile},stdio:['ignore','pipe','pipe']});
let output=''; child.stdout.on('data',d=>output+=d); child.stderr.on('data',d=>output+=d);
const wait=(ms)=>new Promise(r=>setTimeout(r,ms));
try{
  for(let i=0;i<30;i++){await wait(200);try{const response=await fetch(`http://127.0.0.1:${port}/api/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:'admin',password:'admin123'})});if(response.ok){const payload=await response.json();console.log(JSON.stringify({cleanStart:true,login:payload.success,role:payload.data.user.role,dbCreated:fs.existsSync(dbFile),serverOutput:output.trim()},null,2));break;}}catch{}}
}finally{child.kill('SIGTERM');await wait(500);for(const suffix of ['', '-wal', '-shm']){try{fs.unlinkSync(dbFile+suffix);}catch{}}}
